{
  "shot": {
    "composition": "中景镜头，使用35mm镜头，索尼VENICE摄影机，浅景深，焦点集中在薛夫人身上，背景人物与环境适度虚化以突出主体。",
    "camera_motion": "静止镜头，无任何移动或摇晃，保持稳定构图以强调人物的凝视与情绪张力。"
  },
  "subject": {
    "description": "25岁的中国女性，东亚面孔，面容清冷精致，长发乌黑柔顺，盘成古典发髻，发髻上点缀珍珠发饰，眉目如画，眼神锐利，唇角微扬，表情冷艳而含蓄，身姿挺拔优雅。",
    "wardrobe": "身着一袭淡蓝色内衬配粉色长裙的汉服，外披一件绣有金色凤凰纹样的红色长袍，腰间系有淡粉色丝带，脚穿绣花木履，整体服饰华丽且符合古代贵族婚宴场合。"
  },
  "scene": {
    "location": "侯府内厅堂，装饰富丽堂皇，红柱金瓦，雕梁画栋，中央设婚宴长桌，两侧宾客席位对称排列。",
    "time_of_day": "正午时分，阳光透过雕花窗棂洒入厅堂。",
    "environment": "厅内张灯结彩，红绸幔帐垂挂，桌案上摆满精致酒席，宾客们身着各色华服，或交谈或举杯，氛围热闹而庄重，背景中隐约可见香炉与烛台。"
  },
  "visual_details": {
    "action": "薛夫人冷峻地扫视全场宾客，随后嘴角轻扬，拿起酒杯与宾客对饮，动作从容而优雅。",
    "props": "婚宴长桌、酒杯、酒壶、果盘、红绸幔帐、雕花木凳、香炉、烛台、宾客服饰、宴席菜肴。",
    "action_sequence": [
      "0-1s: 薛夫人站立于婚宴中央，冷冽视线扫过四周宾客，嘴角微扬，眼神凌厉如刀。",
      "1-2s: 她缓缓抬起右手，轻握酒杯，目光锁定前方一位宾客，嘴角笑意加深，仿佛在无声嘲讽。",
      "2-3s: 薛夫人将酒杯轻轻一抬，与前方宾客对视，随后优雅地将酒杯倾斜，一饮而尽，动作流畅而从容。"
    ]
  },
  "cinematography": {
    "lighting": "自然光为主，辅以厅堂内暖黄色灯笼与烛光，光线柔和但富有层次，照亮薛夫人面部轮廓与服饰细节，营造庄重而略带压迫感的氛围。",
    "tone": "冷艳、优雅、克制，带有古典权谋与贵族气场，情感张力内敛而深邃，视觉风格精致华丽，富有戏剧张力。"
  }
}
